// Анимация при скролле.
if (!document.querySelector(".constructorActive")) {
	if (!containers) var containers;
	if (!appearOptions) var appearOptions;
	if (!appearObserver) var appearObserver;
	setTimeout(() => {
		containers = document.querySelectorAll(".section .container");
		appearOptions = {
			root: null,
			rootMargin: "-100px 0px -100px 0px",
			// threshold: 0.1,
		};
		appearObserver = new IntersectionObserver((entries, observer) => {
			entries.forEach((entry) => {
				if (entry.isIntersecting) {
					// entry.target.classList.remove("animation-out");
					if (!entry.target.classList.contains("animation-in")) {
						animate({
							duration: 1000,
							timing: function easeOutBounce(x) {
								const n1 = 7.5625;
								const d1 = 2.75;

								if (x < 1 / d1) {
									return n1 * x * x;
								} else if (x < 2 / d1) {
									return n1 * (x -= 1.5 / d1) * x + 0.75;
								} else if (x < 2.5 / d1) {
									return n1 * (x -= 2.25 / d1) * x + 0.9375;
								} else {
									return n1 * (x -= 2.625 / d1) * x + 0.984375;
								}
							},
							draw: function (progress) {
								entry.target.style.transform = `translateY(${50 - progress * 50}px`;
								entry.target.style.opacity = progress * 100;

								if (progress == 1) {
									entry.target.classList.add("animation-in");
									entry.target.style.transition = "0s";
									entry.target.style.opacity = "";
									entry.target.style.transform = "";
									entry.target.style.transition = "transform .3s cubic-bezier(0, 0.55, 0.45, 1), opacity .3s cubic-bezier(0, 0.55, 0.45, 1)";
								}
							},
						});
					}

					entry.target.classList.add("animation-in");
				}
			});
		}, appearOptions);

		if (containers.length) {
			containers.forEach((item) => {
				appearObserver.observe(item);
			});
		}
	}, 500);
}

function animate({ timing, draw, duration }) {
	let start = performance.now();

	requestAnimationFrame(function animate(time) {
		// timeFraction изменяется от 0 до 1
		let timeFraction = (time - start) / duration;
		if (timeFraction > 1) timeFraction = 1;

		// вычисление текущего состояния анимации
		let progress = timing(timeFraction);

		draw(progress); // отрисовать её

		if (timeFraction < 1) {
			requestAnimationFrame(animate);
		}
	});
}

