function windowListener() {
	if ((window.matchMedia("(max-width: 1263px)").matches && prevWindowWidth > 1263) || (window.matchMedia("(min-width: 1264px)").matches && prevWindowWidth < 1264)) {
		resizeAllH1s();
	}
	prevWindowWidth = window.innerWidth;
}

