//// Детектим переключение медиа, end.

function h1Length(el, max_size, min_size, min_length, max_length) {
	// Макс размер (<=6 символов) - 298px.
	// Мин размер (>=64 символов) - 80px.
	// Между ними плавно уменьшается.
	let az5 = 0;

	if (window.matchMedia("(max-width: 1263px)").matches) {
		max_size = 72;
		min_size = 30;
	}

	document.querySelectorAll(el).forEach((item) => {
		let chars_length = item.textContent.replace(/\s{2,}/g, " ").length;
		let stepSize = ((max_size - min_size) / (max_length - min_length)).toFixed(2);

		item.style.fontSize = "";

		if (!(chars_length <= min_length) && !(chars_length > max_length)) {
			let currentSize = window.getComputedStyle(item).getPropertyValue("font-size").replace("px", "");
			let newSize = currentSize - stepSize * (chars_length - min_length);
			item.style.fontSize = `${newSize}px`;
		}

		if (chars_length > max_length) {
			item.style.fontSize = `${min_size}px`;
		}

		while (isOverflownX(item)) {
			if (az5 > 50) {
				console.log("%c☢☢☢ az5 called ☢☢☢", `color: green; background: yellow;`);
				break;
			}
			az5++;
			h1OverflowingWordsCorrect(item);
		}

		h1LinesCorrect(item, chars_length, max_length, min_size);
	});
}

function h1OverflowingWordsCorrect(el) {
	let currentSize = window.getComputedStyle(el).getPropertyValue("font-size").replace("px", "");
	el.style.fontSize = `${currentSize - 4}px`;
}

function h1LinesCorrect(el, chars_length, max_length, min_size) {
	let linesNumber = getNumlines(el);
	if ((chars_length < 23 && linesNumber <= 2) || (chars_length >= 23 && chars_length <= 64 && linesNumber <= 3) || chars_length > 64) {
		return;
	}
	let currentSize = window.getComputedStyle(el).getPropertyValue("font-size").replace("px", "");

	if (currentSize <= min_size) {
		return;
	}

	el.style.fontSize = `${currentSize - 1}px`;

	h1LinesCorrect(el, chars_length, max_length, min_size);
}

// Определение количества строк.
function getStyle(el, styleProp) {
	var x = el;
	if (x.currentStyle) var y = x.currentStyle[styleProp];
	else if (window.getComputedStyle) var y = document.defaultView.getComputedStyle(x, null).getPropertyValue(styleProp);
	return y;
}
function calculateLineHeight(element) {
	var lineHeight = parseInt(getStyle(element, "line-height"), 10);
	var clone;
	var singleLineHeight;
	var doubleLineHeight;

	if (isNaN(lineHeight)) {
		clone = element.cloneNode();
		clone.innerHTML = "<br>";
		element.appendChild(clone);
		singleLineHeight = clone.offsetHeight;
		clone.innerHTML = "<br><br>";
		doubleLineHeight = clone.offsetHeight;
		element.removeChild(clone);
		lineHeight = doubleLineHeight - singleLineHeight;
	}

	return lineHeight;
}

function getNumlines(el) {
	if (!document.querySelector(".container--test")) {
		let testContainer = document.createElement("div");
		testContainer.classList.add("container");
		testContainer.classList.add("container--test");

		document.body.append(testContainer);
	}
	el.style.transform = "scale(1)";

	let copy = document.createElement(el.tagName);
	copy.innerHTML = el.innerHTML;

	if (document.querySelector("#temp-h1")) {
		document.querySelector("#temp-h1").remove();
	}

	copy.setAttribute("class", el.getAttribute("class"));
	copy.setAttribute("id", "temp-h1");
	let originalWidth = el.getBoundingClientRect().width;
	copy.setAttribute("style", `${el.getAttribute("style")} opacity: 0 !important; transform: none !important; width: ${originalWidth}px`);
	el.style.transform = "";

	if (el.querySelectorAll("br").length) {
		copy.innerHTML = copy.innerHTML.replace(/<br\s*\/?>/gi, " ");
	}

	if (document.querySelector(".container--test")) {
		document.querySelector(".container--test").append(copy);
	} else {
		el.closest("body").append(copy);
	}

	let num = Math.round(copy.offsetHeight / calculateLineHeight(copy));

	copy.remove();

	return num}
