function cta2SubmitFunction(evt) {
	evt.preventDefault();

	let ctaForm = evt.currentTarget.closest(".cta2");

	if (!ctaForm) {
		return false;
	}

	let ctaFormInputs = ctaForm.querySelectorAll(".cta2__input");
	let ctaFormCurrentStatus = "";

	ctaFormInputs.forEach((input) => {
		if ((input.type == "checkbox" && !input.checked) || !input.value) {
			ctaFormCurrentStatus = "error";
			input.classList.add("cta2__input--error");
		} else {
			input.classList.remove("cta2__input--error");
		}
	});

	if (ctaFormCurrentStatus != "error") {
		sendData(evt.currentTarget)
			.then((response) => {
				return response.json();
			})
			.then((json) => {
				if (json.status == "ok") {
					let errorInputs = ctaForm.querySelectorAll(".cta2__input--error");

					if (errorInputs.length) {
						errorInputs.forEach((input) => {
							input.classList.remove("cta2__input--error");
						});
					}

					document.body.classList.add("scrollOff");
					document.querySelector(".overlay").classList.add("overlay--visible");
					document.querySelector(".popUp").classList.add("popUp--visible");

					document.querySelector(".popUp__close").classList.add("popUp__close--visible");
				} else {
					json.errorFields.forEach((field) => {
						ctaForm.querySelector(`input[name='${field}']`).classList.add("cta2__input--error");
					});
				}
			})
			.catch((err) => {
				console.log("Something wrong!", err);
			});
	}
}

function cta2Layout() {
	document.querySelectorAll(".cta2__form").forEach((item) => {
		if (item.querySelector(".cta2__formInputsList")) {
			item.querySelector(".cta2__formInputsList").append(item.querySelector(".cta2__submit"));
		}
	});
}

function cta2Init() {
	cta2Unmount();

	cta2Layout();

	let allCta2Forms = document.querySelectorAll(".cta2__form");
	if (allCta2Forms.length) {
		allCta2Forms.forEach((item) => {
			item.addEventListener("submit", cta2SubmitFunction);
		});
	}

	let allCta2Wrappers = document.querySelectorAll(".cta2__wrapper");
	if (allCta2Wrappers.length) {
		allCta2Wrappers.forEach((item) => {
			if (item.getBoundingClientRect().height / 2 > 400) {
				item.style.setProperty("--margin-top", "-400px");
			} else {
				item.style.setProperty("--margin-top", `${item.getBoundingClientRect().height / -2}px`);
			}
		});
	}
}

function cta2Unmount() {
	if (document.querySelectorAll(".cta2__form").length) {
		document.querySelectorAll(".cta2__form").forEach((item) => {
			item.removeEventListener("submit", cta2SubmitFunction);
		});
	}

	document.querySelectorAll(".cta2__form").forEach((item) => {
		item.append(item.querySelector(".cta2__submit"));
	});
}

